const {phases,questions,sections}=COURSE;
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const states=['New','Learning','Independent','Retained','Transfer'];let saved={q:{},notes:{},plan:'12',read:[]};try{const v=JSON.parse(localStorage.getItem('dsa-path-v1'));if(v&&v.q&&v.notes&&Array.isArray(v.read))saved={...saved,...v}}catch{}
let filter={search:'',phase:'all',tier:'all',status:'all',pattern:'all'},timerSeconds=2700,timer=null;
function persist(){try{localStorage.setItem('dsa-path-v1',JSON.stringify(saved))}catch{toast('Storage unavailable. Export your progress to keep a backup.')}}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000)}
function status(q){return saved.q[q.id]?.status||'New'}function complete(q){return ['Independent','Retained','Transfer'].includes(status(q))}function qs(p){return questions.filter(q=>q.phase===p)}
const navs=[['path','','Learn'],['patterns','','Patterns'],['questions','','Questions']];
function heading(k,t,d){return `<div class="page-head"><div><h1>${t}</h1><p class="sub">${d}</p></div></div>`}
function phaseCard(p){let all=qs(p.id),done=all.filter(complete).length,pct=all.length?Math.round(done/all.length*100):0;return `<article class="card"><a class="stretched" href="#phase/${p.id}"><div class="card-top"><span class="phase-icon">${String(p.id).padStart(2,'0')}</span><span class="tag">${p.id===16?'ADVANCED':p.id===17?'PUT IT TOGETHER':p.id<2?'FOUNDATIONS':'CORE PATH'}</span></div><h3>${esc(p.title)}</h3><p>${all.length} questions · Theory & practical exercises</p><div class="bar"><i style="width:${pct}%"></i></div><div class="card-bottom"><span>${done} / ${all.length} independent</span><span>${pct}% &nbsp; →</span></div></a></article>`}
const art=`<svg class="tree" viewBox="0 0 260 205" aria-label="A branching learning path" role="img"><g fill="none" stroke="#b0c193" stroke-width="1.5"><path d="M130 34V69M60 101V69H200V101M60 125V155H25V177M60 155H95V177M200 125V155H165V177M200 155H235V177"/></g><g fill="#f9fbef" stroke="#b8c79c"><rect x="106" y="10" width="48" height="45" rx="12"/><rect x="37" y="86" width="46" height="44" rx="11"/><rect x="177" y="86" width="46" height="44" rx="11"/><circle cx="25" cy="181" r="16"/><circle cx="95" cy="181" r="16"/><circle cx="165" cy="181" r="16"/><circle cx="235" cy="181" r="16"/></g><g fill="#5f7950" font-family="monospace" font-size="15" text-anchor="middle"><text x="130" y="39">{ }</text><text x="60" y="114">01</text><text x="200" y="114">10</text><text x="25" y="186">✓</text><text x="95" y="186">+</text><text x="165" y="186">⌁</text><text x="235" y="186">∞</text></g></svg>`;
function overview(){const done=questions.filter(complete).length,next=phases.find(p=>qs(p.id).some(q=>!complete(q)))||phases[0];return heading('','Your study desk','Learn, practice, and review at your own pace.')+`<div class="home-progress"><div><strong>${done} of ${questions.length}</strong><span> questions solved independently</span></div><a class="btn" href="#phase/${next.id}">Continue learning →</a></div><div class="section-head"><h2>Study</h2></div><div class="home-links"><a href="#path"><strong>Learning path</strong><span>18 phases, from foundations to advanced algorithms</span><b>→</b></a><a href="#patterns"><strong>Patterns</strong><span>${COURSE.patterns.length} techniques with examples and practice ladders</span><b>→</b></a><a href="#mastery"><strong>Interview mastery</strong><span>Deep dives, proofs, and follow-ups</span><b>→</b></a><a href="#questions"><strong>Question bank</strong><span>Find a problem and track your progress</span><b>→</b></a><a href="#labs"><strong>Interview labs</strong><span>Six original exercises with progressive hints</span><b>→</b></a><a href="#review"><strong>Review & notes</strong><span>Revisit questions and keep your learning record</span><b>→</b></a></div><div class="section-head" style="margin-top:32px"><h2>Next phase</h2><a href="#path">View all →</a></div>${phaseCard(next)}`;}
function phase(id){const p=phases.find(p=>p.id===+id);if(!p)return '<p>Phase not found. <a href="#path">Return to the path.</a></p>';return heading('PHASE '+String(p.id).padStart(2,'0'),esc(p.title),'Read, build, practice, then test your understanding.')+`<div class="controls"><a class="btn light" href="#path">← All phases</a><button class="btn" onclick="filter={search:'',phase:'${p.id}',tier:'all',status:'all',pattern:'all'};location.hash='questions'">Practice ${qs(p.id).length} questions →</button><button class="btn light" onclick="toggleRead(${p.id})">${saved.read.includes(p.id)?'✓ Theory read':'Mark theory as read'}</button></div><div class="reader">${p.html}</div><div class="panel" style="margin-top:20px"><h3>Your phase notes</h3><textarea id="phase-note" aria-label="Phase notes" placeholder="What clicked? What should you revisit?">${esc(saved.notes[p.id]||'')}</textarea><p class="note">Notes save as you type in this browser.</p></div><div class="controls">${p.id>0?`<a class="btn light" href="#phase/${p.id-1}">← Previous phase</a>`:''}${p.id<17?`<a class="btn" href="#phase/${p.id+1}">Next phase →</a>`:''}</div>`}
function toggleRead(id){saved.read=saved.read.includes(id)?saved.read.filter(x=>x!==id):[...saved.read,id];persist();render()}
function questionPage(){return heading('PRACTICE WITH INTENTION','Your question bank','Search, filter, and build mastery. Repeated questions are tracked once.')+`<div class="toolbar"><input id="search" aria-label="Search questions" placeholder="Search by title or LeetCode ID…" value="${esc(filter.search)}"><select id="phase-filter" aria-label="Filter phase"><option value="all">All phases</option>${phases.map(p=>`<option value="${p.id}" ${filter.phase==p.id?'selected':''}>${p.id}. ${esc(p.title)}</option>`).join('')}</select><select id="pattern-filter" aria-label="Filter by pattern"><option value="all">All patterns</option>${COURSE.patterns.map(p=>`<option value="${p.id}" ${filter.pattern==p.id?'selected':''}>${esc(p.title)}</option>`).join('')}</select><select id="tier-filter" aria-label="Filter priority">${['all','Core','Extension','Mastery'].map(v=>`<option ${filter.tier===v?'selected':''} value="${v}">${v==='all'?'All priorities':v}</option>`).join('')}</select><select id="status-filter" aria-label="Filter status">${['all',...states].map(v=>`<option ${filter.status===v?'selected':''} value="${v}">${v==='all'?'All progress':v}</option>`).join('')}</select></div><div id="question-results"></div><p class="note">Open a question to find it in LeetCode by title or ID. Priority indicates learning order, not difficulty. Pattern mappings are curated and can overlap. Some resources may require an account.</p>`}
function results(){let list=questions.filter(q=>(q.title+' '+q.id).toLowerCase().includes(filter.search.toLowerCase())&&(filter.phase==='all'||q.phase==filter.phase)&&(filter.tier==='all'||q.tier===filter.tier)&&(filter.status==='all'||status(q)===filter.status)&&(!filter.pattern||filter.pattern==='all'||COURSE.patterns[Number(filter.pattern)]?.ids.includes(q.id)));$('#question-results').innerHTML=`<p class="note">${list.length} questions · ${list.filter(complete).length} independently solved</p><div class="table-wrap"><table><thead><tr><th>QUESTION</th><th>PHASE</th><th>PRIORITY</th><th>PROGRESS</th></tr></thead><tbody>${list.map(q=>`<tr><td><a target="_blank" rel="noopener" href="https://leetcode.com/problemset/?search=${encodeURIComponent(q.title)}"><span class="note">${q.id.padStart(4,'0')}</span> &nbsp; ${esc(q.title)} ↗</a></td><td><a href="#phase/${q.phase}">${String(q.phase).padStart(2,'0')}</a></td><td><span class="tag">${q.tier}</span></td><td><select aria-label="Progress for ${esc(q.title)}" data-q="${q.id}">${states.map(s=>`<option ${status(q)===s?'selected':''}>${s}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table>${!list.length?'<div class="empty">No questions match. Try a different search or filter.</div>':''}</div>`;document.querySelectorAll('[data-q]').forEach(el=>el.onchange=()=>{saved.q[el.dataset.q]={status:el.value,updated:Date.now(),due:Date.now()+({'New':0,'Learning':1,'Independent':3,'Retained':14,'Transfer':30}[el.value]*86400000)};persist();results()})}
function sectionStarts(s){return sections.find(x=>x.title.startsWith(s))?.html||''}
function plans(){return heading('MAKE ROOM FOR PROGRESS','A plan that fits your timeline','Choose your pace, then use the diagnostic to find your starting point.')+`<div class="grid">${[['20','Build from the foundations','10–14 hours / week'],['12','The balanced route','12–16 hours / week'],['4','Focused revision','For learners with DSA experience'],['7','Emergency refresh','7 days · existing knowledge required']].map(([n,t,d])=>`<div class="card"><div class="eyebrow">${n} ${n==='7'?'DAYS':'WEEKS'}</div><h3>${t}</h3><p>${d}</p><button class="btn ${saved.plan===n?'':'light'}" onclick="saved.plan='${n}';persist();render()">${saved.plan===n?'✓ Selected plan':'Choose this plan'}</button></div>`).join('')}</div><div class="reader" style="margin-top:25px">${sectionStarts('1.')}${sectionStarts('2.')}</div>`}
function review(){let due=questions.filter(q=>saved.q[q.id]&&status(q)!=='New'&&saved.q[q.id].due<=Date.now());return heading('TURN PRACTICE INTO RETENTION','Review & learning notes','Your progress stays in this browser. Export a backup to keep it portable.')+`<div class="controls"><button class="btn" onclick="exportProgress()">Export progress ↓</button><label class="btn light" for="import-file">Import progress ↑</label><input hidden type="file" id="import-file" accept="application/json"></div><div class="panel"><h3>${due.length} questions ready for review</h3>${due.length?due.map(q=>`<div class="review-item"><span>${q.id} · ${esc(q.title)}</span><a href="#questions" onclick="filter.search='${q.id}';filter.phase='all';filter.status='all';filter.tier='all';filter.pattern='all'">Revisit →</a></div>`).join(''):'<p class="sub">Nothing due yet. Update a question’s progress to schedule a review.</p>'}<p class="note">Learning: 1 day · Independent: 3 days · Retained: 14 days · Transfer: 30 days. Update the status after each review to schedule the next one.</p></div><div class="panel" style="margin-top:18px"><h3>Your learning journal</h3><textarea id="journal" aria-label="Learning journal" placeholder="Track your mistakes, invariants, mock scores, and next steps…">${esc(saved.notes.journal||'')}</textarea><p class="note">Saved automatically. No cross-device sync; use export/import.</p></div><div class="reader" style="margin-top:18px">${sectionStarts('8.')}</div>`}
function exportProgress(){const b=new Blob([JSON.stringify(saved,null,2)],{type:'application/json'}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='dsa-path-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function timeText(){return String(Math.floor(timerSeconds/60)).padStart(2,'0')+':'+String(timerSeconds%60).padStart(2,'0')}
function mocks(){return heading('PRACTICE THE WHOLE CONVERSATION','Your interview rehearsal','Clarify, reason, implement, test, and explain.')+`<div class="panel"><div class="eyebrow">45-MINUTE PRACTICE ROUND</div><div class="timer" id="timer">${timeText()}</div><div class="controls"><button class="btn" id="timer-toggle" onclick="toggleTimer()">${timer?'Pause':'Start timer'}</button><button class="btn light" onclick="resetTimer()">Reset</button></div><p class="note">The timer runs while this page stays open. Use an unseen problem for a realistic mock.</p></div><div class="reader" style="margin-top:20px">${sectionStarts('7.')}</div>`}
let endTime=0;function toggleTimer(){if(timer){clearInterval(timer);timer=null}else{endTime=Date.now()+timerSeconds*1000;timer=setInterval(()=>{timerSeconds=Math.max(0,Math.ceil((endTime-Date.now())/1000));if($('#timer'))$('#timer').textContent=timeText();if(timerSeconds===0){clearInterval(timer);timer=null;if($('#timer-toggle'))$('#timer-toggle').textContent='Start timer';toast('Time is up. Take a moment to review your approach.')}},250)}if($('#timer-toggle'))$('#timer-toggle').textContent=timer?'Pause':'Start timer'}function resetTimer(){clearInterval(timer);timer=null;timerSeconds=2700;if($('#timer'))$('#timer').textContent=timeText();if($('#timer-toggle'))$('#timer-toggle').textContent='Start timer'}
function resources(){return heading('YOUR REFERENCE SHELF','Theory, templates & resources','Keep the complete guide close. Look up what you need, when you need it.')+`<div class="tabs">${[['3.','Foundations'],['5.','Pattern selection'],['6.','Code templates'],['9.','Resources'],['What','About this guide']].map(([id,t])=>`<button data-section="${id}">${t}</button>`).join('')}</div><div class="reader" id="resource-content">${sectionStarts('3.')}</div>`}
function render(){let [page,id]=(location.hash.slice(1)||'path').split('/');$('#nav').innerHTML=navs.map(([key,icon,label])=>`<a href="#${key}" class="${page===key||(page==='phase'&&key==='path')||(['pattern','pattern-drill','pattern-trace'].includes(page)&&key==='patterns')||(['mastery','deep','plans'].includes(page)&&key==='path')||(['labs','lab','mocks','readiness'].includes(page)&&key==='practice')?'active':''}"><span>${icon}</span>${label}</a>`).join('');$('#breadcrumb').textContent='Workspace / '+(navs.find(n=>n[0]===page)?.[2]||'Learning path');$('#view').innerHTML=page==='practice'?practiceHome():page==='patterns'?patternsPage():page==='pattern'?patternPage(id):page==='pattern-drill'?patternDrill():page==='pattern-trace'?patternTrace():page==='mastery'?masteryHome():page==='deep'?deepPage(id):page==='labs'?labHome():page==='lab'?labPage(id):page==='readiness'?readinessPage():page==='overview'?overview():page==='path'?heading('THE COMPLETE CURRICULUM','From first principles to confident solutions','Work through the foundations, then explore advanced lessons and pattern practice.')+`<div class="controls"><a class="btn light" href="#plans">Choose a study plan</a><a class="btn light" href="#mastery">Advanced lessons</a><a class="btn light" href="#patterns">Browse patterns</a></div><div class="grid modern-list">${phases.map(phaseCard).join('')}</div>`:page==='phase'?phase(id):page==='questions'?questionPage():page==='plans'?plans():page==='review'?review():page==='mocks'?mocks():page==='resources'?resources():overview();
if(page==='questions'){results();$('#search').oninput=e=>{filter.search=e.target.value;results()};for(const [el,key] of [['phase-filter','phase'],['tier-filter','tier'],['status-filter','status']])$('#'+el).onchange=e=>{filter[key]=e.target.value;results()}}
if($('#phase-note'))$('#phase-note').oninput=e=>{saved.notes[id]=e.target.value;persist()};if($('#journal'))$('#journal').oninput=e=>{saved.notes.journal=e.target.value;persist()};
if($('#import-file'))$('#import-file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>2000000)throw Error();const v=JSON.parse(await f.text());if(!v.q||typeof v.q!=='object'||!v.notes||typeof v.notes!=='object'||!Array.isArray(v.read)||!['20','12','4','7'].includes(v.plan))throw Error();const clean={q:{},notes:{},read:v.read.filter(x=>Number.isInteger(x)&&x>=0&&x<18),plan:v.plan};for(const q of questions){const r=v.q[q.id];if(r&&states.includes(r.status)&&Number.isFinite(r.updated)&&Number.isFinite(r.due))clean.q[q.id]=r}for(const [k,val]of Object.entries(v.notes))if((k==='journal'||/^\d+$/.test(k))&&typeof val==='string')clean.notes[k]=val;if(!confirm('Replace progress in this browser with this backup? Export first if you want to preserve your current progress.'))return;saved=clean;persist();render();toast('Progress imported.')}catch{toast('This file is not a valid DSA Path progress backup.')}};
document.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>{$('#resource-content').innerHTML=sectionStarts(b.dataset.section);document.querySelectorAll('[data-section]').forEach(x=>x.classList.toggle('active',x===b))});if(page==='resources')document.querySelector('[data-section]').classList.add('active');masteryBind();patternBind();}

function practiceHome(){return heading('','Practice','Apply what you learned, then review the evidence.')+`<div class="home-links"><a href="#labs"><strong>Interview labs</strong><span>Original prompts with hints, proofs, and follow-ups</span><b>→</b></a><a href="#pattern-drill"><strong>Pattern recognition</strong><span>Choose a technique from the constraints</span><b>→</b></a><a href="#mocks"><strong>Timed mock</strong><span>Practice a complete coding interview</span><b>→</b></a><a href="#readiness"><strong>Readiness & history</strong><span>Record performance and identify what to improve</span><b>→</b></a></div>`;}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();
